function delay(ms, value, fail = false) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (fail) reject(new Error(`${value} failed`));
      else resolve(value);
    }, ms);
  });
}

Promise.all([delay(30, 'a'), delay(10, 'b'), delay(20, 'c')]).then((results) => {
  console.log('all:', results);
});

Promise.race([delay(30, 'slow'), delay(5, 'fast')]).then((winner) => {
  console.log('race winner:', winner);
});

Promise.allSettled([delay(15, 'ok'), delay(10, 'bad', true)]).then((results) => {
  console.log('settled:', results.map((r) => r.status));
});
